package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.graphics.*;
import android.location.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import org.json.*;

/** Process-separated pending attempts and temporal matching, solely in ui.tests workspaces. */
public final class PendingRecoveryInstrumentation extends Instrumentation {
    private String phase;private MainActivity activity;private LogStore logs;
    interface Action{void run()throws Exception;}
    private void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private void main(Action action)throws Exception{Throwable[] e={null};runOnMainSync(()->{try{action.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new RuntimeException(e[0]);}
    private Object get(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
    private void set(Object o,String n,Object v)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
    private Object call(Object o,String n,Class<?>[] types,Object... values)throws Exception{java.lang.reflect.Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o,values);}
    private Bundle draft()throws Exception{return (Bundle)get(activity,"draft");}
    @SuppressWarnings("unchecked") private void noFix()throws Exception{ForegroundLocation shared=ForegroundLocation.get(activity);shared.refresh(true);activity.getSystemService(LocationManager.class).removeUpdates(shared);Map<String,CancellationSignal> requests=(Map<String,CancellationSignal>)get(shared,"requests");for(CancellationSignal token:requests.values())token.cancel();requests.clear();for(String p:(Set<String>)get(shared,"providers"))requests.put(p,new CancellationSignal());Location absent=new Location("test-no-fix");absent.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());set(shared,"latest",absent);set(activity,"latest",null);set(shared,"noFixSince",SystemClock.elapsedRealtime());call(activity,"startLocation",new Class<?>[]{});}
    private void snapshot(String name)throws Exception{waitForIdleSync();Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"native screenshot "+name);File folder=new File(activity.getExternalFilesDir(null),"pending-recovery");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){check(image.compress(Bitmap.CompressFormat.PNG,100,out),"screenshot write");}finally{image.recycle();}}
    private Bundle bundle(String roll,long tap,long elapsed)throws Exception{Bundle b=new Bundle();b.putBoolean("newRecord",true);b.putBoolean("quick",true);b.putString("request",UUID.randomUUID().toString());b.putString("recordRoll",roll);b.putString("returnScreen","dashboard");b.putString("offset","-10");b.putInt("recordZone",480);b.putLong("recordTap",tap);PendingExposure.markTime(activity,b,elapsed);return b;}
    private void point(ForegroundLocation shared,Location p)throws Exception{set(shared,"latest",null);shared.onLocationChanged(p);}
    private void basic()throws Exception{
        main(()->{noFix();String roll=logs.addRoll("Automatic recovery","Test","",400,36);Bundle b=bundle(roll,System.currentTimeMillis()-30000,SystemClock.elapsedRealtime()-30000);set(activity,"draft",b);set(activity,"rollId",roll);call(activity,"commitNewRecord",new Class<?>[]{});check(PendingExposure.load(activity)!=null&&logs.roll(roll).count==0,"pending durable before point/no frame increment");check(PendingExposure.load(new WorkspaceContext(Workspace.root(activity),UUID.randomUUID().toString()))==null,"pending attempt isolated from other workspaces");((Runnable)get(activity,"locationTimeout")).run();ForegroundLocation shared=ForegroundLocation.get(activity);Location unrelated=LocatedRecordInstrumentation.fix();point(shared,unrelated);});
        snapshot("pending-original-time");
        main(()->{check(draft()!=null&&logs.roll(draft().getString("recordRoll")).count==0,"later unrelated point never fills old exposure");Location match=LocatedRecordInstrumentation.fix();long event=draft().getLong("recordElapsed");match.setElapsedRealtimeNanos((event+10000)*1000000L);match.setTime(draft().getLong("recordTap")+10000);match.setSpeed(0);point(ForegroundLocation.get(activity),match);});
        main(()->{check(draft()==null&&PendingExposure.load(activity)==null,"matching callback completes after timeout without retry click");LogStore.Roll roll=logs.rolls().get(0);LogStore.Shot shot=logs.shots(roll.id).get(0);check(shot.lat!=null&&shot.captured==shot.tapped-10000,"automatic completion retains tap/offset/location");
            noFix();Bundle b=bundle(roll.id,System.currentTimeMillis(),SystemClock.elapsedRealtime());set(activity,"draft",b);call(activity,"commitNewRecord",new Class<?>[]{});call(activity,"cancelLocatedRecord",new Class<?>[]{});check(PendingExposure.load(activity)==null&&logs.roll(roll.id).count==1,"cancel clears durable draft without adding frame");
            Bundle legacy=bundle(roll.id,System.currentTimeMillis(),SystemClock.elapsedRealtime());legacy.putBoolean("newRecord",false);legacy.putString("locationAction","editor");legacy.putString("memo","Keep unfinished editor");legacy.putBoolean("pendingPersisted",true);set(activity,"draft",legacy);set(activity,"screen","editor");call(activity,"render",new Class<?>[]{});PendingExposure.save(activity,legacy,"editor");call(activity,"cancelLocatedRecord",new Class<?>[]{});check(draft()!=null&&!draft().getBoolean("pendingPersisted")&&draft().getString("memo").equals("Keep unfinished editor"),"legacy cancellation keeps editor values without stale persistence marker");set(activity,"draft",null);set(activity,"screen","dashboard");call(activity,"render",new Class<?>[]{});
            Location current=LocatedRecordInstrumentation.fix();Bundle anchor=bundle(roll.id,System.currentTimeMillis(),SystemClock.elapsedRealtime());check(PendingExposure.matches(activity,anchor,current),"live matching fix");anchor.putInt("recordBoot",PendingExposure.boot(activity)+1);anchor.putString("recordProcess",UUID.randomUUID().toString());check(!PendingExposure.matches(activity,anchor,current)&&PendingExposure.needsConfirmation(activity,anchor),"reboot does not reuse old monotonic anchor");PendingExposure.confirmHere(activity,anchor);check(PendingExposure.matches(activity,anchor,current),"explicit scene confirmation uses new anchor while preserving original tap");
            ForegroundLocation shared=ForegroundLocation.get(activity);Location good=LocatedRecordInstrumentation.fix();good.setSpeed(0);good.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-45000000000L);set(shared,"latest",good);Location moving=LocatedRecordInstrumentation.fix();moving.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-20000000000L);moving.setSpeed(15);call(shared,"acceptFix",new Class<?>[]{Location.class,String.class},moving,"系统缓存");check(shared.current()==null,"unusable newer cached motion invalidates old stationary position");shared.onLocationChanged(good);check(shared.current()==null,"older callback never revives cache after cached motion");String diagnostic=shared.diagnostics();check(diagnostic.contains("系统缓存")&&!diagnostic.contains("31.2304")&&!diagnostic.contains("121.4737"),"diagnostic has sources and no coordinates");
            File corrupt=new File(activity.getFilesDir(),"pending-exposure.json");try(FileOutputStream out=new FileOutputStream(corrupt)){out.write("broken".getBytes("UTF-8"));}boolean rejected=false;try{PendingExposure.load(activity);}catch(Exception expected){rejected=true;}check(rejected&&corrupt.isFile(),"corrupt draft rejected and preserved");PendingExposure.clear(activity);call(activity,"locationDiagnostics",new Class<?>[]{});
        });
        snapshot("location-diagnostics");
    }
    private void prepare(boolean photo)throws Exception{
        main(()->{noFix();String roll=logs.addRoll("Persistent recovery","Test400","",400,36);long tap=System.currentTimeMillis()-30000,elapsed=SystemClock.elapsedRealtime()-30000;Bundle b=bundle(roll,tap,elapsed);if(photo){Bitmap image=Bitmap.createBitmap(120,120,Bitmap.Config.ARGB_8888);image.eraseColor(Color.BLUE);String token=UUID.randomUUID().toString();ReferencePhotos.capture(activity,token,image);image.recycle();b.putBoolean("quick",false);b.putString("referenceToken",token);b.putString("aperture","8");b.putString("shutter","1/125");b.putString("memo","Private test memo");}set(activity,"draft",b);set(activity,"rollId",roll);call(activity,"commitNewRecord",new Class<?>[]{});((Runnable)get(activity,"locationTimeout")).run();PendingExposure.Saved saved=PendingExposure.load(activity);check(saved!=null&&saved.draft.getLong("recordTap")==tap&&logs.roll(roll).count==0,"prepare persists exact original tap and leaves count unchanged");if(photo){String token=b.getString("referenceToken");check(ReferencePhotos.draft(activity,token).getParentFile().equals(activity.getFilesDir()),"meter photo retained outside disposable cache");new File(activity.getCacheDir(),"meter-reference-"+token+".jpg").delete();check(ReferencePhotos.draft(activity,token).isFile(),"cache eviction cannot remove retained photo");}
            getTargetContext().getSharedPreferences("pending-recovery-test",0).edit().putString("workspace",Workspace.current(activity)).putString("roll",roll).putLong("tap",tap).putLong("event",elapsed).putString("id",photo?b.getString("referenceToken"):b.getString("request")).commit();
        });
    }
    private void resume(boolean photo)throws Exception{
        SharedPreferences state=getTargetContext().getSharedPreferences("pending-recovery-test",0);String roll=state.getString("roll",""),id=state.getString("id","");long tap=state.getLong("tap",0),event=state.getLong("event",0);
        main(()->{if(logs.roll(roll).count==0){check(draft()!=null&&draft().getLong("recordTap")==tap,"fresh process restores original pending attempt");noFix();Location p=LocatedRecordInstrumentation.fix();p.setElapsedRealtimeNanos((event+10000)*1000000L);p.setTime(tap+10000);p.setSpeed(0);point(ForegroundLocation.get(activity),p);}});
        main(()->{check(logs.roll(roll).count==1&&PendingExposure.load(activity)==null&&draft()==null,"new process automatically completes one located record");LogStore.Shot shot=logs.shot(id);check(shot.tapped==tap&&shot.captured==tap-10000&&shot.lat!=null,"stable request/original timestamp/location survive process restart");if(photo){check(ReferencePhotos.forShot(logs,id).equals(id)&&ReferencePhotos.file(activity,logs,id).isFile(),"retained photo commits with located exposure");check(!new File(activity.getFilesDir(),"pending-reference-"+id+".jpg").exists(),"retained draft cleared only after transaction");}
            Bundle stale=bundle(roll,tap,event);stale.putString("request",id);if(photo){stale.putBoolean("quick",false);stale.putString("referenceToken",id);Bitmap image=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);ReferencePhotos.capture(activity,id,image);image.recycle();}PendingExposure.save(activity,stale,"dashboard");check(PendingExposure.alreadySaved(activity,logs,stale)&&logs.roll(roll).count==1&&PendingExposure.load(activity)==null,"commit-before-clear crash is reconciled without duplication");
        });
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);phase=args.getString("phase","basic");start();}
    @Override public void onStart(){Context c=getTargetContext();String previous=Workspace.current(c);Bundle result=new Bundle();boolean passed=false;try{
        check(c.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolation");String workspace=phase.endsWith("resume")?c.getSharedPreferences("pending-recovery-test",0).getString("workspace",""):UUID.randomUUID().toString();Workspace.activate(c,workspace);
        activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();main(()->logs=(LogStore)get(activity,"store"));
        if(phase.equals("basic"))basic();else if(phase.endsWith("prepare"))prepare(phase.startsWith("photo"));else if(phase.endsWith("resume"))resume(phase.startsWith("photo"));else throw new AssertionError("phase");result.putString("stream","PASS: pending recovery "+phase+"; synthetic isolated workspace="+workspace+"\n");passed=true;
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));}finally{try{if(activity!=null)main(()->activity.finish());}catch(Exception ignored){}Workspace.activate(c,previous);}finish(passed?-1:0,result);}
}
